import {analyzePdp} from './pdp-model.mjs?v=20261102-pdp2';
import {assessPdp,pdpText} from './pdp-expert.mjs?v=20261102-pdp2';
import {baselineFigure,forecastFigure,contextFigure,svgOnly} from './pdp-charts.mjs?v=20261102-pdp2';
import {esc,num,table,flow,field,readFile,download,downloadRows} from './ui.mjs';
const S={rows:[],cases:[],original:null,source:'',run:null,expert:null,error:'',cfg:{baseYear:2025,asOf:'2026-10',fitMonths:24,updateMonths:6,horizon:12,bootstrap:400,seed:42,warningPct:10,severePct:20,consecutive:2,gainPct:0,density:.85,scale:'log'}};
let demo=[];
export function initializePdp(rows,cases){demo=rows;S.rows=rows;S.cases=cases;S.source='A区块生成月度场景，非新疆油田实测';defaults();compute();}
function defaults(){const latest=[...S.rows].sort((a,b)=>String(a.month).localeCompare(String(b.month))).at(-1);if(latest?.month){S.cfg.baseYear=Number(latest.month.slice(0,4))-1;S.cfg.asOf=latest.month;S.cfg.plannedWells=Number(latest.active_wells);}}
function compute(){try{const run=analyzePdp(S.rows,{...S.cfg,source:S.source,externalBaseline:S.original});S.run=run;S.expert=assessPdp(run,S.cases,{density:S.cfg.density});S.error='';}catch(e){S.run=null;S.expert=null;S.error=e.message;}}
export function pdpSummary(){if(!S.run)return null;const r=S.run;return {source:r.source,freezeDate:r.freezeDate,asOf:r.asOf,baselineSource:r.baselineSource,baselineModel:r.baselineModel,updatedModel:r.updatedModel,metrics:r.metrics,current:r.current,forecast:r.forecast,expert:S.expert,intervalNote:r.intervalNote};}
function box(title,body,tag=''){return `<section class="panel pdp-panel"><div class="panel-head"><h2>${title}</h2>${tag}</div><div class="panel-body">${body}</div></section>`;}
const upload=(id,label,note)=>`<div class="file-box"><label for="pdp-file-${id}">${label}</label><input id="pdp-file-${id}" data-pdp-upload="${id}" type="file" accept=".csv,.json"><small>${note}</small></div>`;
const levelTag=level=>`<span class="tag ${level==='红'?'red':level==='绿'?'green':level==='蓝'?'blue':level==='灰'?'gray':''}">${level}色</span>`;
function controls(){const c=S.cfg;return `<details class="pdp-config" open><summary>数据、冻结基准与模型参数</summary><div class="upload-grid">${upload('monthly','上传月度生产数据','CSV/JSON，每月一行：month、oil_tonnes、active_wells；water_m3、pressure_mpa等可选。')}${upload('original','上传上年末已发布预测表（可选）','month、forecast_oil_tonnes、issued_on；ci_low/ci_high、pi_low/pi_high可选。可含多年预测；发布日不得晚于冻结日。')}</div><div class="tool-form pdp-form">${field('pdp-base-year','冻结基准年份（年末）',c.baseYear)}<label>当年截至月份<input id="pdp-asof" type="month" value="${esc(c.asOf)}"></label>${field('pdp-fit','基准有效拟合月数',c.fitMonths)}${field('pdp-update','更新有效拟合月数',c.updateMonths)}${field('pdp-horizon','后续预测月数',c.horizon)}${field('pdp-bootstrap','Bootstrap重复次数',c.bootstrap)}${field('pdp-warning','关注偏差阈值 / %',c.warningPct)}${field('pdp-severe','严重偏差阈值 / %',c.severePct)}${field('pdp-consecutive','连续偏低月数',c.consecutive)}${field('pdp-wells','条件情景：已有在产井数',c.plannedWells??0)}${field('pdp-gain','专家输入条件增幅 / %（非估计效果）',c.gainPct)}${field('pdp-density','原油密度假设 / 吨·标准立方米⁻¹',c.density,.01)}<label>曲线坐标<select id="pdp-scale"><option value="log" ${c.scale==='log'?'selected':''}>半对数（参照原图）</option><option value="linear" ${c.scale==='linear'?'selected':''}>线性（含零产量）</option></select></label></div><div class="row"><button class="btn primary" data-pdp="run">冻结基准对比 · 预警 · 专家研判</button><button class="btn" data-pdp="demo">载入生成演示</button>${S.original?'<button class="btn" data-pdp="clear-plan">移除上传计划，改用研究基准</button>':''}<a class="btn" href="data/pdp-monthly.csv" download>↓ 月度样例CSV</a><button class="btn" data-pdp="export" ${!S.run?'disabled':''}>↓ 分析与预测CSV</button><button class="btn" data-pdp="report" ${!S.run?'disabled':''}>↓ 专家研判报告</button></div><p class="tiny" style="margin-top:10px">月油为吨/月，产水为标准立方米/月，在产井为月平均井数；计算先除以日历天与在产井，避免2月/31天月份及井数变化被误读为单井递减。来源：${esc(S.source)}。${S.original?'当前使用用户原始年末计划，不重拟合其预测值。':'无原计划时，仅用冻结日前资料拟合研究基准，不使用当年实际回填。'}</p></details>`;}
function metrics(r){return `<div class="kpis pdp-kpis"><article class="kpi"><label>当年可比月累计实际 / 吨</label><strong>${num(r.metrics.actualTotal,0)}</strong><p>${r.metrics.comparedMonths}个有观测且有计划的月份</p></article><article class="kpi"><label>同期冻结预测 / 吨</label><strong>${num(r.metrics.predictedTotal,0)}</strong><p>${r.freezeDate}冻结版本</p></article><article class="kpi"><label>累计偏差</label><strong>${num(r.metrics.cumulativeDeviation)}<small>%</small></strong><p>实际减预测，以预测为分母</p></article><article class="kpi"><label>触发预警月份</label><strong>${r.metrics.redMonths}<small>红 / ${r.metrics.yellowMonths}黄</small></strong><p>工程阈值与统计提示并用</p></article></div>`;}
export function renderPdpWorkbench(){const r=S.run;return `<div class="pdp-workbench"><div class="pdp-intro"><span class="section-label">YEAR-END BASELINE / PDP DYNAMIC REVIEW</span><h2>年末冻结基准 · 月度偏产预警 · 专家措施研判</h2><p>参照提供的动态法评估曲线，以年末基准和当年月产作对照，再对后续产量给出条件预测。默认是生成区块示例，未使用原图数值，也不是新疆现场实测或认证PDP。</p></div>${controls()}${S.error?`<div class="error-box" role="alert">${esc(S.error)}</div>`:''}${!r?'<div class="empty">请补充有效历史月报或年末预测表后运行；不会显示旧数据的分析结果。</div>':`${metrics(r)}${box('图1 · 上年末冻结PDP产量预测与当前月度实绩',baselineFigure(r,S.cfg.scale)+`<div class="note">绿色虚线：${r.baseYear}年末冻结预测；品红方点：当年月产；红/黄圈：触发预警的观测。半对数轴不显示零值曲线段，零产量方点标在图底，可切换线性坐标核对。${r.baselineSource==='原始年末计划上传'?'原计划未提供的置信/预测区间不补造。':''}</div><details class="pdp-context"><summary>展开配套监测：单井月油、产水、在产井数（基准月=100）</summary>${contextFigure(r)}</details>`,`<button class="btn small" data-pdp="svg1">↓ SVG图</button>`)}${box('图2 · 阶段更新预测与95%置信/预测区间',forecastFigure(r,S.cfg.scale)+`<div class="note">深蓝带：均值95%置信区间（CI）；浅蓝带：单月95%预测区间（PI），额外包含未来观测扰动。起算月${esc(r.forecastOrigin)}，冻结基准保持原版本。${r.gainPct!==0||r.plannedWells!==r.latest.active_wells?'橙色为专家输入的措施条件情景：增幅按6个月时间常数衰减，不代表由历史案例证实的措施效果。橙色情景区间条件于输入增幅和恢复井数，不包含措施效应估计误差。':'当前未输入增产假设，主预测按最新在产井条件延续。'}</div><p class="tiny">${esc(r.intervalNote)} 预测以稳定误差机制和当前阶段可延续为条件；Bootstrap随机种子${r.seed}。${r.warnings.map(esc).join('；')}</p>`,`<button class="btn small" data-pdp="svg2">↓ SVG图</button>`)}${alertTable(r)}${expertView(r,S.expert)}${modelView(r)}${forecastTable(r)}`}</div>`;}
function alertTable(r){return box('月度偏差与预警证据',`<div class="row"><span class="tag red">红：严重或持续偏低</span><span class="tag">黄：关注偏低</span><span class="tag blue">蓝：超产核查</span><span class="tag green">绿：未触发规则</span><span class="tag gray">灰：缺资料</span></div><div class="table-wrap gap"><table><thead><tr><th>月份</th><th>冻结预测 / 吨</th><th>实际 / 吨</th><th>偏差 / %</th><th>单侧尾概率*</th><th>校正后*</th><th>CUSUM</th><th>预警</th><th>触发依据</th></tr></thead><tbody>${r.current.map(a=>`<tr><td>${a.month}</td><td>${num(a.prediction,0)}</td><td>${num(a.actual,0)}</td><td>${num(a.deviation)}</td><td>${a.p_lower===null?'—':a.p_lower<.000001?'&lt;10⁻⁶':num(a.p_lower,6)}</td><td>${a.p_adjusted===null?'—':a.p_adjusted<.000001?'&lt;10⁻⁶':num(a.p_adjusted,6)}</td><td>${num(a.cusum)}</td><td>${levelTag(a.level)}</td><td class="wrap">${esc(a.reason)}</td></tr>`).join('')}</tbody></table></div><p class="tiny">* 正态近似的下尾概率，按12月Bonferroni校正；不是根因、措施成功或储量失效的概率。冻结基准对本年监测的MAE=${num(r.metrics.MAE)}吨/月，RMSE=${num(r.metrics.RMSE)}吨/月，已有预测区间的观测覆盖=${num(r.metrics.predictionCoverage)}%；这些不是更新模型的独立测试准确率。</p>`);}
function expertView(r,e){return box('自动进入专家研判 · 候选原因与下一步措施',`<div class="row">${levelTag(e.level)}<span class="tag">研判观测月 ${esc(e.month)}</span><span class="tiny">本地可解释规则 + 统计检验 + 历史趋势检索；未调用远程大模型</span></div><div class="pdp-analysis-grid"><article><h3>石油专业证据</h3>${e.petroleum.map(s=>`<p>${esc(s)}</p>`).join('')}</article><article><h3>概率统计解读</h3>${e.statistics.map(s=>`<p>${esc(s)}</p>`).join('')}</article></div><h3 class="gap">历史案例角度 · 公开实测趋势对照</h3><div class="three gap">${e.cases.map(c=>`<article class="method-card"><h3>${esc(c.well??c.id)}</h3><span class="tiny">${esc(c.start??'')}—${esc(c.end??'')} · ${esc(c.source)}</span><p class="explanation">首末30日：产油变化${num(c.oil_change_pct)}%；含水变化${num(c.water_cut_delta_pp)}个百分点；压力变化${num(c.pressure_delta_mpa)}兆帕。</p><p class="tiny">共同特征${c.commonFeatures}项，标准化距离${num(c.distance,3)}（越小越相似）。${esc(c.conclusion)}</p></article>`).join('')||'<p class="tiny">共同特征不足，暂不匹配案例。</p>'}</div><div class="pdp-action-list gap">${e.actions.map(a=>`<article><span class="tag red">${esc(a.priority)}</span><h3>${esc(a.measure)}</h3><p><b>依据：</b>${esc(a.evidence)}</p><p><b>先补齐：</b>${esc(a.confirm)}</p></article>`).join('')}</div><div class="report-card"><h3>综合结论</h3><p class="report">${esc(e.conclusion)}</p><p class="tiny">证据缺口：${e.gaps.map(esc).join('；')}</p></div><div class="timeline">${e.followup.map((s,i)=>`<div><strong>${['下月','1个月','3个月','6个月'][i]}</strong><small>${esc(s)}</small></div>`).join('')}</div><button class="btn primary" data-pdp="assistant">将证据与措施报告送入分析助手 →</button>`);}
function modelView(r){const b=r.baselineModel,u=r.updatedModel;return box('模型名称、结构、数学公式与参数注释',`<div class="grid equal"><article class="method-card"><h3>① 年末冻结模型：Arps指数递减 / 对数线性OLS</h3>${flow(['冻结日前有效月','日历天/在产井归一化','对数线性OLS','冻结全年预测'])}<code>q单井,日 = Q油,月 / (d月 × N在产)\ny=ln(q/q参考) = α + βt + ε\nE[Q月]=exp(α+βt+σ²/2)×d月×N基准\nD月=1−exp(β)；D年=1−exp(12β)</code>${b?table([{p:'α',v:b.alpha,n:'基准起始月的对数单井日产率'}, {p:'β',v:b.beta,n:'月度对数变化率（月⁻¹）'}, {p:'D年',v:100*b.annualDecline,n:'有效年递减率（%）'}, {p:'N样本',v:b.n,n:b.firstMonth+'—'+b.lastMonth}, {p:'R²(对数域)',v:b.r2,n:'样本内拟合，不代表未来准确率'}],[['p','参数'],['v','数值'],['n','注释']]):'<p class="note">原始计划上传：预测值保持原样，原模型参数未提供，不反推编造。</p>'}</article><article class="method-card"><h3>② 更新模型 + 三个月残差块Bootstrap</h3>${flow(['截至月前有效资料','最近有效月OLS','残差块重采样B次','均值CI / 观测PI'])}<code>yᵢ*=α̂+β̂tᵢ+εᵢ,块*\nCI₉₅=[Q₂.₅%(均值*),Q₉₇.₅%(均值*)]\nPI₉₅：另加入未来单月ε新~N(0,σ*²)\n置信带为点位、模型条件性区间</code>${table([{p:'更新β',v:u.beta,n:'月度对数趋势；正值表示增长阶段'}, {p:'σ(log)',v:u.sigmaLog,n:'对数误差标准差'}, {p:'n',v:u.n,n:u.firstMonth+'—'+u.lastMonth+'有效月'}, {p:'块长',v:3,n:'月；保留短期残差相关性'}, {p:'B / seed',v:r.bootstrap,n:'随机种子'+r.seed+'；单次实际计算'+num(r.duration,4)+'秒'}],[['p','参数'],['v','数值'],['n','注释']])}</article><article class="method-card"><h3>③ 偏差预警 + 负向CUSUM</h3>${flow(['同期冻结预测','百分比偏差/PI','连续月 + CUSUM','分级预警'])}<code>δ=(Q实际−Q冻结)/Q冻结×100%\nSₜ=max(0,Sₜ₋₁−zₜ−k)；k=0.5，H=5\np校正=min(1,12×Φ(z))</code><p class="explanation">关注偏差${r.thresholds.warning}%，严重偏差${r.thresholds.severe}%，连续偏低${r.thresholds.consecutive}月。CUSUM与尾概率为模型近似提示；与工程规则并用，不能简单相乘得到根因概率。</p></article><article class="method-card"><h3>④ 专家融合：约束规则 + kNN趋势对照</h3>${flow(['井数/含水/压力证据','候选原因规则','公开趋势相似检索','措施+确认条件'])}<code>d=√mean[(x目标−x案例)²/s²]\ns=[产油20%、含水10pp、压力2MPa、可用性20%]\n至少2项共同特征，返回最近3个案例</code><p class="explanation">距离是相似度刻画，不是成功概率。检索中的产油变化采用当月相对年末的日历天折算日产油变化，不用冻结预测误差代替观测趋势。单井开井时长与区块在产井数只作可用性近似对照，需核实不同尺度与地质条件。措施条件增幅由专家输入，不从缺少施工记录的Volve样本推断因果效果。</p></article></div><div class="source-links gap"><a href="https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/oil-gas-rules" target="_blank" rel="noopener">SEC：Oil and Gas Rules（154.01）</a><a href="https://www.itl.nist.gov/div898/handbook/pmd/section1/pmd131.htm" target="_blank" rel="noopener">NIST：均值置信区间</a><a href="https://itl.nist.gov/div898/handbook/pmd/section1/pmd132.htm" target="_blank" rel="noopener">NIST：未来观测预测区间</a><a href="../agent/data/SOURCES.md">Volve实测来源</a></div><p class="tiny">产水与压力用于证据研判，不直接进入当前指数产量回归。此处按指数模型并用已有生产数据验证；不能在无证据时假设更有利的双曲递减。正式PDP评估还需经济条件、权益、合同、地质与工程可采性等专业审查。</p>`);}
function forecastTable(r){return box('后续逐月预测结果 · 吨/月',table(r.forecast,[['month','预测月份'],['baseline','原冻结基准'],['prediction','维持现状预测'],['ci_low','95%均值CI下限'],['ci_high','95%均值CI上限'],['pi_low','95%单月PI下限'],['pi_high','95%单月PI上限'],['scenario','输入措施条件情景']],36),'');}
function readControls(){const read=id=>{const value=document.getElementById(id)?.value;if(value===undefined||value==='')throw Error('请补齐参数：'+id);const n=Number(value);if(!Number.isFinite(n))throw Error('无效数字：'+id);return n;};return {...S.cfg,baseYear:read('pdp-base-year'),asOf:document.getElementById('pdp-asof').value,fitMonths:read('pdp-fit'),updateMonths:read('pdp-update'),horizon:read('pdp-horizon'),bootstrap:read('pdp-bootstrap'),warningPct:read('pdp-warning'),severePct:read('pdp-severe'),consecutive:read('pdp-consecutive'),plannedWells:read('pdp-wells'),gainPct:read('pdp-gain'),density:read('pdp-density'),scale:document.getElementById('pdp-scale').value};}
export async function pdpAction(action,{render,notify,handoff}){try{if(action==='run'){const cfg=readControls();if(cfg.density<=0||cfg.density>2)throw Error('密度需大于0且不大于2吨/标准立方米');S.cfg=cfg;compute();if(S.error)throw Error(S.error);notify('冻结基准对比、后续区间与专家研判已完成');}else if(action==='demo'){S.rows=demo;S.original=null;S.source='A区块生成月度场景，非新疆油田实测';defaults();compute();}else if(action==='clear-plan'){S.original=null;compute();}else if(action==='export'){if(!S.run)throw Error('请先运行');const r=S.run;downloadRows('PDP-月度预警及后续预测.csv',[...r.current.map(a=>({...a,record_type:'冻结基准监测',source:r.source,freeze_date:r.freezeDate,unit:'吨/月'})),...r.forecast.map(a=>({...a,record_type:'后续条件预测',source:r.source,freeze_date:r.freezeDate,unit:'吨/月',interval_note:r.intervalNote}))]);return;}else if(action==='report'){if(!S.run)throw Error('请先运行');download('PDP-专家研判与措施.md',pdpText(S.run,S.expert));return;}else if(action==='svg1'||action==='svg2'){if(!S.run)throw Error('请先运行');download('PDP-'+(action==='svg1'?'年末冻结基准对比':'更新预测与区间')+'.svg',svgOnly(action==='svg1'?baselineFigure(S.run,S.cfg.scale):forecastFigure(S.run,S.cfg.scale)),'image/svg+xml;charset=utf-8');return;}else if(action==='assistant'){if(!S.run)throw Error('请先运行');handoff(pdpSummary(),pdpText(S.run,S.expert));return;}}catch(e){S.error=e.message;notify(e.message);}render();}
export async function pdpUpload(kind,file,{render,notify}){try{const rows=await readFile(file);S.run=null;S.expert=null;if(kind==='monthly'){S.rows=rows;S.source='用户上传：'+file.name+'（来源待核实）';defaults();}else S.original=rows;compute();if(S.error)throw Error(S.error);notify('已载入月度资料并生成冻结对比与专家研判');}catch(e){S.error=e.message;}render();}
